# slug → 看板定义（路由/前端用）
BY_SLUG: Dict[str, Dict[str, Any]] = {d['slug']: d for d in DASHBOARDS}

# 前端菜单用：轻量清单（不含 SQL，避免首屏传大 JSON）
CATALOG: List[Dict[str, Any]] = [
    {
        'slug': d['slug'],
        'page': 'finebi_' + d['slug'],
        'title': d['title'] or d['name'],
        'name': d['name'],
        'category': d['category'],
        'tags': d['tags'],
        'widgets': len(d['widgets']),
    }
    for d in DASHBOARDS
]
